'use client';

import { useState, useEffect } from 'react';
import { Plus, X, Server, Globe, Key, Clock, ShieldCheck, Trash2 } from 'lucide-react';
import Topbar from '../components/Topbar';

export default function ITAssetsPage() {
  const [assets, setAssets] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [toastMsg, setToastMsg] = useState('');

  // Modal State for New Asset
  const [showModal, setShowModal] = useState(false);
  const [mName, setMName] = useState('');
  const [mType, setMType] = useState('DOMAIN');
  const [mVendor, setMVendor] = useState('');
  const [mPurchase, setMPurchase] = useState('');
  const [mExpiry, setMExpiry] = useState('');
  const [mCost, setMCost] = useState('');
  const [mAutoRenew, setMAutoRenew] = useState(false);

  // Modal State for Password Reminder
  const [showPwdModal, setShowPwdModal] = useState(false);
  const [selectedAssetId, setSelectedAssetId] = useState<string | null>(null);
  const [pwdLastChanged, setPwdLastChanged] = useState('');
  const [pwdInterval, setPwdInterval] = useState('3');

  function showToast(m: string) {
    setToastMsg(m);
    setTimeout(() => setToastMsg(''), 2500);
  }

  const fetchAssets = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/it-assets');
      const data = await res.json();
      setAssets(data);
    } catch (e) {
      console.error(e);
      showToast('Error loading assets.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAssets();
  }, []);

  const addAsset = async () => {
    if (!mName || !mType || !mExpiry) {
      showToast('Name, Type, and Expiry are required.');
      return;
    }
    try {
      await fetch('/api/it-assets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          name: mName, asset_type: mType, vendor: mVendor, 
          purchase_date: mPurchase, expiry_date: mExpiry, 
          cost: parseFloat(mCost) || 0, auto_renew: mAutoRenew 
        })
      });
      setShowModal(false);
      setMName(''); setMVendor(''); setMPurchase(''); setMExpiry(''); setMCost(''); setMAutoRenew(false);
      showToast('Asset added!');
      fetchAssets();
    } catch (e) {
      showToast('Error saving asset.');
    }
  };

  const deleteAsset = async (id: string) => {
    if (!confirm('Delete this asset? This also deletes its password reminders.')) return;
    try {
      await fetch('/api/it-assets/' + id, { method: 'DELETE' });
      showToast('Deleted.');
      fetchAssets();
    } catch (e) {
      showToast('Error deleting.');
    }
  };

  const addPasswordReminder = async () => {
    if (!selectedAssetId || !pwdLastChanged) {
      showToast('Please select a date.');
      return;
    }
    try {
      await fetch(`/api/it-assets/${selectedAssetId}/password-reminder`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ last_changed_date: pwdLastChanged, reminder_interval_months: parseInt(pwdInterval) })
      });
      setShowPwdModal(false);
      showToast('Reminder set!');
      fetchAssets();
    } catch (e) {
      showToast('Error setting reminder.');
    }
  };

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const getUrgency = (expiry: string) => {
    const exp = new Date(expiry);
    const diff = Math.ceil((exp.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    if (diff < 0) return { color: 'var(--muted)', label: 'Expired', days: diff };
    if (diff <= 7) return { color: 'var(--red)', label: 'Urgent', days: diff };
    if (diff <= 30) return { color: 'var(--orange)', label: 'Soon', days: diff };
    return { color: 'var(--green)', label: 'Safe', days: diff };
  };

  const totalCost = assets.reduce((s, a) => s + a.cost, 0);
  const urgentCount = assets.filter(a => getUrgency(a.expiry_date).days > 0 && getUrgency(a.expiry_date).days <= 30).length;

  return (
    <>
      <Topbar title="IT Assets & Subscriptions">
        <button className="btn btn-primary" onClick={() => setShowModal(true)}>
          <Plus size={15} /> Add Asset
        </button>
      </Topbar>

      <div className="scroll">
        <div className="stats" style={{ marginBottom: '20px' }}>
          <div className="s-card"><div className="s-lbl">Total Assets</div><div className="s-val" style={{ color: 'var(--primary)' }}>{assets.length}</div></div>
          <div className="s-card"><div className="s-lbl">Expiring in &lt; 30d</div><div className="s-val" style={{ color: 'var(--orange)' }}>{urgentCount}</div></div>
          <div className="s-card"><div className="s-lbl">Total Value</div><div className="s-val" style={{ color: 'var(--green)' }}>৳ {Math.round(totalCost).toLocaleString('en-BD')}</div></div>
        </div>

        <div className="card">
          <div className="card-head">
            <h3>Asset Registry</h3>
          </div>
          <table>
            <thead>
              <tr>
                <th>Asset</th>
                <th>Vendor</th>
                <th>Expiry Date</th>
                <th>Password Reminder</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr className="empty-r"><td colSpan={5}>Loading...</td></tr>
              ) : assets.length === 0 ? (
                <tr className="empty-r"><td colSpan={5}>No assets registered yet.</td></tr>
              ) : (
                assets.map(a => {
                  const urgency = getUrgency(a.expiry_date);
                  const Icon = a.asset_type === 'DOMAIN' ? Globe : a.asset_type === 'HOSTING' ? Server : Key;
                  
                  return (
                    <tr key={a.id}>
                      <td>
                        <div className="av-cell">
                          <div className="av" style={{ background: 'rgba(79,126,255,.1)', color: 'var(--primary)' }}>
                            <Icon size={14} />
                          </div>
                          <div>
                            <div style={{ fontWeight: 600, fontSize: '.9rem' }}>{a.name}</div>
                            <div style={{ fontSize: '.7rem', color: 'var(--muted)', marginTop: '2px' }}>{a.asset_type}</div>
                          </div>
                        </div>
                      </td>
                      <td>{a.vendor || '—'}</td>
                      <td>
                        <div style={{ fontWeight: 600, color: urgency.color }}>
                          {new Date(a.expiry_date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}
                        </div>
                        <div style={{ fontSize: '.7rem', color: 'var(--muted)', marginTop: '2px' }}>
                          {urgency.days > 0 ? `in ${urgency.days} day(s)` : urgency.days === 0 ? 'Expires today' : 'Expired'}
                        </div>
                      </td>
                      <td>
                        {a.password_reminder ? (
                          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '.8rem', color: 'var(--muted)' }}>
                            <ShieldCheck size={14} color="var(--green)" />
                            Every {a.password_reminder.reminder_interval_months} mo
                          </div>
                        ) : (
                          <button className="btn btn-ghost btn-sm" onClick={() => { setSelectedAssetId(a.id); setShowPwdModal(true); }}>
                            <Clock size={12} /> Set
                          </button>
                        )}
                      </td>
                      <td>
                        <button className="btn btn-ghost btn-sm" style={{ border: 'none' }} onClick={() => deleteAsset(a.id)}>
                          <Trash2 size={15} />
                        </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="veil on" onClick={(e) => { if (e.target === e.currentTarget) setShowModal(false); }}>
          <div className="modal">
            <div className="mhead">
              <h3>Add IT Asset</h3>
              <button className="xbtn" onClick={() => setShowModal(false)}><X size={16} /></button>
            </div>
            <div className="fg"><label>Name</label><input placeholder="e.g. alliedone.com" value={mName} onChange={e => setMName(e.target.value)} /></div>
            <div className="drow">
              <div className="fg">
                <label>Type</label>
                <select value={mType} onChange={e => setMType(e.target.value)}>
                  <option value="DOMAIN">Domain</option>
                  <option value="HOSTING">Hosting / VPS</option>
                  <option value="LICENSE">Software License</option>
                  <option value="SUBSCRIPTION">SaaS Subscription</option>
                </select>
              </div>
              <div className="fg"><label>Vendor</label><input placeholder="e.g. Namecheap" value={mVendor} onChange={e => setMVendor(e.target.value)} /></div>
            </div>
            <div className="drow">
              <div className="fg"><label>Purchase Date</label><input type="date" value={mPurchase} onChange={e => setMPurchase(e.target.value)} /></div>
              <div className="fg"><label>Expiry Date</label><input type="date" value={mExpiry} onChange={e => setMExpiry(e.target.value)} /></div>
            </div>
            <div className="drow">
              <div className="fg"><label>Cost (৳)</label><input type="number" placeholder="0" value={mCost} onChange={e => setMCost(e.target.value)} /></div>
              <div className="fg" style={{ display: 'flex', alignItems: 'center', marginTop: '24px' }}>
                <input type="checkbox" checked={mAutoRenew} onChange={e => setMAutoRenew(e.target.checked)} style={{ width: 'auto', marginRight: '8px' }} />
                <span style={{ fontSize: '.8rem', color: 'var(--muted)' }}>Auto Renew</span>
              </div>
            </div>
            <div className="mfooter">
              <button className="btn btn-ghost" onClick={() => setShowModal(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={addAsset}>Save Asset</button>
            </div>
          </div>
        </div>
      )}

      {showPwdModal && (
        <div className="veil on" onClick={(e) => { if (e.target === e.currentTarget) setShowPwdModal(false); }}>
          <div className="modal">
            <div className="mhead">
              <h3>Set Password Reminder</h3>
              <button className="xbtn" onClick={() => setShowPwdModal(false)}><X size={16} /></button>
            </div>
            <div className="fg"><label>Last Changed Date</label><input type="date" value={pwdLastChanged} onChange={e => setPwdLastChanged(e.target.value)} /></div>
            <div className="fg">
              <label>Reminder Interval</label>
              <select value={pwdInterval} onChange={e => setPwdInterval(e.target.value)}>
                <option value="1">Every 1 Month</option>
                <option value="3">Every 3 Months</option>
                <option value="6">Every 6 Months</option>
              </select>
            </div>
            <div className="mfooter">
              <button className="btn btn-ghost" onClick={() => setShowPwdModal(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={addPasswordReminder}>Save Reminder</button>
            </div>
          </div>
        </div>
      )}

      {toastMsg && <div className="toast on">{toastMsg}</div>}
    </>
  );
}
